from typing import Any

VALID_CURRENCIES = ("USD", "EUR", "GBP")
_store = {}

def _is_uuid(s: Any) -> bool:
    if not isinstance(s, str):
        return False
    parts = s.split("-")
    if len(parts) != 5:
        return False
    for part, n in zip(parts, [8, 4, 4, 4, 12]):
        if len(part) != n or any(c not in "0123456789abcdef" for c in part):
            return False
    return True


def validate_create_payment(body: Any) -> dict:
    errors = {}
    if not isinstance(body, dict):
        return {"body": ["must be an object"]}
    amount = body.get("amountCents")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        errors["amountCents"] = ["must be a positive integer"]
    if body.get("currency") not in VALID_CURRENCIES:
        errors["currency"] = ["must be one of USD, EUR, GBP"]
    if not _is_uuid(body.get("idempotencyKey")):
        errors["idempotencyKey"] = ["must be a UUID"]
    return errors


def create_payment(body: Any) -> dict:
    errors = validate_create_payment(body)
    if errors:
        return {"status": 422, "body": {"error": "invalid_request", "fields": errors}}
    key = body["idempotencyKey"]
    if key in _store:
        return {"status": 200, "body": _store[key]}
    record = {
        "id": "11111111-1111-1111-1111-111111111111",
        "status": "succeeded",
        "amountCents": body["amountCents"],
    }
    _store[key] = record
    return {"status": 201, "body": record}


KEY_A = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"
REQUESTS = [
    {"amountCents": 500, "currency": "USD", "idempotencyKey": KEY_A},
    {"amountCents": 500, "currency": "USD", "idempotencyKey": KEY_A},
    {"amountCents": -10, "currency": "USD", "idempotencyKey": "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"},
    {"amountCents": 200, "currency": "JPY", "idempotencyKey": "not-a-uuid"},
]

for i, req in enumerate(REQUESTS):
    res = create_payment(req)
    if res["status"] == 422:
        fields = ",".join(sorted(res["body"]["fields"].keys()))
        print(f"req{i}: {res['status']} invalid_request fields={fields}")
    else:
        b = res["body"]
        print(f"req{i}: {res['status']} {b.get('status')} amount={b.get('amountCents')}")

