import json

PROBLEM_TYPE = "about:blank#invalid-order"
PROBLEM_TITLE = "Order failed validation"


def field_error(field, code, message):
    return {"field": field, "code": code, "message": message}


def validate_create_order(payload):
    errors = []
    sku = payload.get("sku")
    if not isinstance(sku, str) or len(sku) == 0:
        errors.append(field_error("sku", "too_small", "sku must be a non-empty string"))
    quantity = payload.get("quantity")
    if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
        errors.append(field_error("quantity", "not_positive", "quantity must be a positive integer"))
    if errors:
        return {"type": PROBLEM_TYPE, "title": PROBLEM_TITLE, "status": 422, "errors": errors}
    return {"status": 201, "sku": sku, "quantity": quantity}


