from abc import ABC, abstractmethod
from dataclasses import dataclass


@dataclass(frozen=True)
class Order:
    order_id: str
    symbol: str
    qty: int


# The boundary: the service knows ONLY this shape.
# No SQL, no ORM, no table names leak past this interface.
class OrderRepository(ABC):
    @abstractmethod
    def find_by_idempotency_key(self, key):
        ...

    @abstractmethod
    def save(self, order, idempotency_key):
        ...


# One implementation owns persistence. Here it's in-memory, but it could
# just as well be Postgres behind the exact same interface.
class InMemoryOrderRepository(OrderRepository):
    def __init__(self):
        self._by_key = {}
        self.write_count = 0

    def find_by_idempotency_key(self, key):
        return self._by_key.get(key)

    def save(self, order, idempotency_key):
        self.write_count += 1
        self._by_key[idempotency_key] = order
        return order


class OrderService:
    def __init__(self, orders):
        # Depend on the interface, not a concrete DB.
        self._orders = orders

    def place(self, order, idempotency_key):
        # TODO: implement idempotent placement using ONLY self._orders:
        #   1. Look up any prior order for this idempotency_key.
        #   2. If one exists, return it unchanged (replay -> no re-write).
        #   3. Otherwise, save the new order under this key and return it.
        prior = self._orders.find_by_idempotency_key(idempotency_key)
        if prior is not None:
            return prior
        return self._orders.save(order, idempotency_key)


repo = InMemoryOrderRepository()
service = OrderService(repo)

r1 = service.place(Order("ord-1", "AAPL", 10), "key-abc")
r2 = service.place(Order("ord-2", "AAPL", 10), "key-abc")  # replay of key-abc
r3 = service.place(Order("ord-3", "MSFT", 5), "key-xyz")

print(f"r1={r1.order_id}")
print(f"r2={r2.order_id}")
print(f"replay_same={r1 is r2}")
print(f"r3={r3.order_id}")
print(f"writes={repo.write_count}")

