from dataclasses import dataclass


@dataclass(frozen=True)
class Account:
    id: str
    owner_id: str
    tenant_id: str


ACCOUNTS = [
    Account("acct_1", owner_id="user_a", tenant_id="tnt_1"),
    Account("acct_2", owner_id="user_b", tenant_id="tnt_1"),
    Account("acct_3", owner_id="user_a", tenant_id="tnt_2"),
]


@dataclass(frozen=True)
class Caller:
    id: str
    tenant_id: str


def authorize_transfer(account_id, caller):
    account = next(
        (a for a in ACCOUNTS
         if a.id == account_id and a.tenant_id == caller.tenant_id),
        None,
    )
    if account is None or account.owner_id != caller.id:
        return 404
    return 200


REQUESTS = [
    ("acct_1", Caller("user_a", "tnt_1")),
    ("acct_1", Caller("user_b", "tnt_1")),
    ("acct_2", Caller("user_a", "tnt_1")),
    ("acct_3", Caller("user_a", "tnt_1")),
    ("acct_9", Caller("user_a", "tnt_1")),
    ("acct_3", Caller("user_a", "tnt_2")),
]


def main():
    for account_id, caller in REQUESTS:
        status = authorize_transfer(account_id, caller)
        print(f"{account_id} {caller.id} {caller.tenant_id} -> {status}")


if __name__ == "__main__":
    main()

